public function total(string $unit): float
{
    $realUnit = $unit = strtolower($unit);

    if (\in_array($unit, ['days', 'weeks'])) {
        $realUnit = 'dayz';
    } elseif (!\in_array($unit, ['microseconds', 'milliseconds', 'seconds', 'minutes', 'hours', 'dayz', 'months', 'years'])) {
        throw new UnknownUnitException($unit);
    }

    $this->checkStartAndEnd();

    if ($this->startDate && $this->endDate) {
        $diff = $this->startDate->diffInUnit($unit, $this->endDate);

        return $this->absolute ? abs($diff) : $diff;
    }

    $result = 0;
    $cumulativeFactor = 0;
    $unitFound = false;
    $factors = self::getFlipCascadeFactors();
    $daysPerWeek = (int) static::getDaysPerWeek();

    $values = [
        'years' => $this->years,
        'months' => $this->months,
        'weeks' => (int) ($this->d / $daysPerWeek),
        'dayz' => fmod($this->d, $daysPerWeek),
        'hours' => $this->hours,
        'minutes' => $this->minutes,
        'seconds' => $this->seconds,
        'milliseconds' => (int) ($this->microseconds / UnitValue::MICROSECONDS_PER_MILLISECOND),
        'microseconds' => $this->microseconds % UnitValue::MICROSECONDS_PER_MILLISECOND,
