    foreach ($factors as $source => [$target, $factor]) {
        if ($source === $realUnit) {
            $unitFound = true;
            $value = $values[$source];
            $result += $value;
            $cumulativeFactor = 1;
        }

        if ($factor === false) {
            if ($unitFound) {
                break;
            }

            $result = 0;
            $cumulativeFactor = 0;

            continue;
        }

        if ($target === $realUnit) {
            $unitFound = true;
        }

        if ($cumulativeFactor) {
            $cumulativeFactor *= $factor;
            $result += $values[$target] * $cumulativeFactor;

            continue;
        }

        $value = $values[$source];

        $result = ($result + $value) / $factor;
    }

    if (isset($target) && !$cumulativeFactor) {
        $result += $values[$target];
    }

